// Regenerate db/schema.ts from the local DB (supabase/migrations is the source of truth).
// drizzle-kit pull output needs patches to type-check; they are applied here so the result is reproducible.
import { execSync } from "node:child_process";
import { readFileSync, writeFileSync, rmSync } from "node:fs";

execSync("drizzle-kit pull", { stdio: "inherit" });

const header =
  "/* eslint-disable */\n" +
  "// GENERATED by `pnpm db:pull` from the local Supabase DB. Do not edit by hand.\n" +
  "// Typed queries only: this file never creates or migrates the schema.\n";

let schema = readFileSync("db/introspect/schema.ts", "utf8");
schema = schema
  // custom tsvector type (see db/types.ts)
  .replace(/^(import .*?\n)/, `$1import { tsvector } from "./types"\n`)
  // tsvector is introspected as unknown()
  .replace(/unknown\("search"\)/g, 'tsvector("search")')
  // text[] default '{}' is introspected as [""] (a one-element array)
  .replace(/\.array\(\)\.default\(\[""\]\)/g, ".array().default(sql`'{}'::text[]`)")
  // Drop foreignKey() blocks: introspection mis-pairs composite FK columns, and the
  // recipes <-> recipe_versions cycle breaks type inference. The DB enforces FKs;
  // Drizzle only needs them for migrations, which it never runs here.
  .replace(/\tforeignKey\(\{[\s\S]*?\}\)(\.onDelete\("[a-z ]+"\))?(\.onUpdate\("[a-z ]+"\))?,\n/g, "")
  .replace("// TODO: failed to parse database type 'tsvector'\n\t", "")
  .replace(/, foreignKey|foreignKey, /, "");
if (/\bunknown\(/.test(schema)) throw new Error("db-pull: unhandled unknown() column type in schema.ts");

writeFileSync("db/schema.ts", header + schema);
// db/relations.ts is hand-written: generated relations join composite FKs on the wrong columns.
rmSync("db/introspect", { recursive: true, force: true }); // drop generated SQL/meta: not migrations
console.log("db-pull: wrote db/schema.ts");
